with open(json_file) as f:
    demos = json.load(f)

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find background (most common color)
    from collections import Counter
    all_colors = []
    for row in grid:
        all_colors.extend(row)
    background = Counter(all_colors).most_common(1)[0][0]

    # Find uniform rows (all cells same value, not background or size 1)
    uniform_rows = set()
    for i in range(h):
        row_colors = set(grid[i])
        if len(row_colors) == 1 and grid[i][0] != background and len(row_colors) != 1:
            # Actually let me check: this might be background...
            pass
        # Check if row is all same color
        if all(grid[i][j] == grid[i][0] for j in range(w)):
            uniform_rows.add(i)

    # Find uniform columns
    uniform_cols = set()
    for j in range(w):
        col_colors = [grid[i][j] for i in range(h)]
        if all(col_colors[0] == col_colors[j] for j in range(h)):
            uniform_cols.add(j)

    # Any cell in uniform row or column -> 2
    out = []
    for i in range(h):
        row = []
        for j in range(w):
            if i in uniform_rows or j in uniform_cols:
                row.append(2)
            else:
                row.append(grid[i][j])
        out.append(row)
    return out

